mapper.select:

SELECT p.* FROM (SELECT  
  WHERE i.owner_id=#{q.owner}

    AND pl.planned_date >= #{q.from} AND pl.planned_date <= #{q.to}

      AND i.status='ACTIVE'

        AND pl.planned_date IS NULL
        AND pl.planned_date < #{q.latestDate}
        AND pl.planned_date >= #{q.earliestDate} AND pl.planned_date <= #{q.latestDate}
        AND FALSE



) p WHERE TRUE





LIMIT #{q.limit}

SELECT p.* FROM (SELECT  
  WHERE s.owner_id=#{q.owner}

    AND pl.planned_date >= #{q.from} AND pl.planned_date <= #{q.to}

      AND (s.status IN ('RUNNING','PAUSED') OR (s.status='DRAFT' AND pl.planned_date IS NULL))

    AND s.status='DRAFT' AND pl.planned_date < #{q.latestDate}
    AND s.status='DRAFT' AND pl.planned_date >= #{q.earliestDate} AND pl.planned_date <= #{q.latestDate}
    AND FALSE


    AND EXISTS(SELECT 1 FROM JSON_TABLE(s.context_json,'$[*]' COLUMNS(
      source_kind VARCHAR(16) PATH '$.kind',item_id VARCHAR(36) PATH '$.itemId')) t
      WHERE t.source_kind='TARGET' AND CAST(t.item_id AS BINARY)=CAST(#{q.targetId} AS BINARY))

) p WHERE TRUE





LIMIT #{q.limit}

SELECT p.* FROM (SELECT   WHERE t.owner_id=#{q.owner}
AND t.target_item_id=#{q.targetId}

  AND t.planned_date >= #{q.from} AND t.planned_date <= #{q.to}
  AND t.status='IN_PROGRESS'
  AND t.status='TODO' AND t.planned_date IS NULL
  AND t.status='TODO' AND t.planned_date < #{q.latestDate}
  AND t.status='TODO' AND t.planned_date >= #{q.earliestDate} AND t.planned_date <= #{q.latestDate}
  AND FALSE

) p WHERE TRUE








LIMIT #{q.limit}

SELECT p.* FROM (SELECT   WHERE a.owner_id=#{q.owner}

    AND pl.planned_date >= #{q.from} AND pl.planned_date <= #{q.to}

      AND a.status='OPEN'

        AND (pl.planned_date IS NULL OR pl.planned_date < #{q.latestDate})
        AND pl.planned_date >= #{q.earliestDate} AND pl.planned_date <= #{q.latestDate}
        AND FALSE



) p WHERE TRUE




LIMIT #{q.limit}

SELECT p.* FROM (SELECT   WHERE e.owner_id=#{q.owner}
AND e.target_id=#{q.targetId}

  AND e.start_at < #{q.windowEnd} AND e.end_at > #{q.windowStart}

    AND e.status='PLANNED'


        AND ((e.reminder_acknowledged_at IS NULL AND e.remind_at <= #{q.asOf}) OR e.end_at <= #{q.asOf})


        AND NOT ((e.reminder_acknowledged_at IS NULL AND e.remind_at <= #{q.asOf}) OR e.end_at <= #{q.asOf})
        AND e.start_at < #{q.dayEnd} AND e.end_at > #{q.dayStart}


        AND NOT ((e.reminder_acknowledged_at IS NULL AND e.remind_at <= #{q.asOf}) OR e.end_at <= #{q.asOf})
        AND e.start_at >= #{q.dayEnd} AND e.start_at < #{q.upcomingEnd}

      AND FALSE



) p WHERE TRUE








LIMIT #{q.limit}
